objs = {
'2a': {(0,5),(1,5),(1,6)}, '2b': {(2,0),(3,0)}, '3': {(2,2),(2,3),(2,4)},
'4': {(3,4),(3,6),(4,4),(4,5),(4,6)}, '5': {(8,3),(8,4)}, '6': {(6,6),(7,6)},
'8a': {(0,3)},'8b': {(5,3)},'8c': {(7,1)},'8d': {(9,5)} }
# all objects, move rightmost first until blocked by final objects/wall
placed=[]
for name,cells in sorted(objs.items(), key=lambda kv:max(c for r,c in kv[1]), reverse=True):
    orig=cells
    while True:
        nxt={(r,c+1) for r,c in cells}
        if any(c>=10 for r,c in nxt) or any(nxt & other for _,other in placed): break
        cells=nxt
    placed.append((name,cells))
    print(name, sorted(cells), 'dx', min(c for r,c in cells)-min(c for r,c in orig))
grid=[[0]*10 for _ in range(10)]
for name,cells in placed:
 color=int(name[0]);
 for r,c in cells: grid[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in grid))
